<script lang="ts">
import type { Snippet } from 'svelte';
import cx from 'classnames';

import { Icon } from '@viamrobotics/prime-core';

let showContent = $state(false);

const toggleContent = () => (showContent = !showContent);

interface Props {
  title?: Snippet;
  subtitle?: Snippet;
  content?: Snippet;
}

const { title, subtitle, content }: Props = $props();
</script>

<button
  class="mb-6 flex items-start gap-2 text-left text-base font-semibold"
  onclick={toggleContent}
  aria-expanded={showContent}
  data-testid="collapsible-button"
>
  <div class={cx('mt-1 transition-all', showContent && 'rotate-90')}>
    <Icon
      name="chevron-right"
      aria-hidden="true"
    />
  </div>
  <div>
    {#if title}
      {@render title()}
    {/if}
    <h3 class="text-sm font-semibold text-subtle-2">
      {#if subtitle}
        {@render subtitle()}
      {/if}
    </h3>
  </div>
</button>

{#if showContent}
  <div
    class="mb-8 ml-6 w-full"
    role="region"
    aria-labelledby="collapsible-button"
  >
    {#if content}
      {@render content()}
    {/if}
  </div>
{/if}
