<!--
@component

A nav container with optional variant: 'primary' | 'secondary'

```svelte
<TabsBar variant='secondary'>
  <Tab
    title='The first tab'
    href="#first"
    isSelected='true' 
  />
  <Tab
    title='The second tab'
    href="#second"
    isSelected='false' 
  />
  <Tab
    title='The third tab'
    href="#third"
    isSelected='false' 
  />
</TabsBar>
```
-->
<script module>
export const CONTEXT_KEY = Symbol('tabs-bar-context');
</script>

<script lang="ts">
import { setContext, type Snippet } from 'svelte';
import { writable } from 'svelte/store';

interface Props {
  /** Accessible label for the tab list */
  'aria-label'?: string;
  /** ID of the element that labels this tab list */
  'aria-labelledby'?: string;
  /** The tab style variant */
  variant?: 'primary' | 'secondary';
  /** Additional CSS classes to apply to the nav element */
  class?: string;
  children?: Snippet;
}

const {
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledby,
  children,
  class: className = '',
  variant = 'primary',
}: Props = $props();

const context = writable(variant);
$effect(() => {
  context.set(variant);
});

setContext(CONTEXT_KEY, context);
</script>

<div
  role="tablist"
  aria-label={ariaLabel}
  aria-labelledby={ariaLabelledby}
  aria-orientation="horizontal"
  class={[
    // Base styles
    'flex min-h-10 flex-wrap items-center sm:px-2',

    // Secondary variant
    variant === 'secondary' && ['gap-4'],

    // Custom classes
    className,
  ]}
>
  {@render children?.()}
</div>
